const LORE={'Mother Bethel':['Church','Founded by Richard Allen in 1794; the mother church of African Methodism and a station on the Underground Railroad. This is the third building on the site, a stuccoed meeting house dedicated in 1841; the congregation has held the lot since 1791.'],'2nd African Presbyterian':['Church','Organized in 1824; its stuccoed Greek Revival meeting house on St. Mary Street, modeled here from the surviving photograph, became a center of abolitionist organizing.'],'Union Baptist':['Church','One of the earliest Black Baptist congregations in the city, on Little Pine Street.'],'Little Union Methodist':['Church','A small Methodist meeting house serving the blocks north of Lombard.'],'"Brick" Wesley Methodist':['Church','Big Wesley, an African Methodist Episcopal Zion church on Lombard Street.'],'Little Wesley Methodist':['Church · Hurst Street','The smaller Wesley congregation, facing Hurst Street, the lane between Fifth and Sixth south of Lombard.'],'1st Black Public School':['School','The Lombard Street Public School, the first public school in Philadelphia built for Black children, later named for the sailmaker and abolitionist James Forten. Modeled on the surviving photograph: a three-story fieldstone schoolhouse with paired round-arched windows.'],'Institute for Colored Youth':['School · 718 Lombard Street','Founded by Quakers in 1837 to train Black teachers; its Lombard Street building opened in 1852. Forerunner of Cheyney University.'],'Philadelphia Institute':['Hall · 717 Lombard Street','A literary and lecture society hall built by Black Philadelphians for debate and self-education.'],'Benezet Hall':['Hall · 506 S. Seventh Street','A meeting hall named for the abolitionist schoolmaster Anthony Benezet, rented for lectures, fairs and society meetings.'],'Home for the Colored Aged and Infirm':['Institution','A residence for elderly Black Philadelphians supported by the community\'s benevolent societies.'],'Amelia Shadd\'s Boarding House':['Boarding house','Kept by Amelia Shadd, whose family were prominent in abolition and emigration circles.'],'Dr. James Bias\' House':['Dwelling','Home and office of Dr. James J. G. Bias, physician, dentist and Underground Railroad operative.'],'Sarah Ash\'s House':['Dwelling','Residence of Sarah Ash, listed among the district\'s Black property holders.'],'Solomon Clarkson\'s House':['Dwelling','Residence of Solomon Clarkson, a property holder in the district.'],'Moral Reform Retreat?':['Institution','Possibly the Moral Reform Retreat, a refuge for women run by Black reformers. Identification uncertain.'],'Soap Factory':['Works','A soap and candle works. Trades like this shared the back streets with dwellings.'],'Steam Drying':['Works','A steam drying establishment, one of the small industries of the district.'],'stable':['Stable',''],'Boyer House':['Boarding house · 505 S. Seventh Street',''],'H.S. Duterte':['Undertaker · 634 Lombard Street','Henrietta S. Duterte took over her late husband Francis\'s undertaking business in 1858, becoming the first woman undertaker in the United States. The parlor doubled as an Underground Railroad station; she is said to have hidden fugitives in coffins and funeral processions.']};

