// ---- street numbers ----
// Post-consolidation numbering read from the 1860 atlas: E-W streets count up westward (odd north, even south);
// N-S streets count up southward (odd east, even west). Where both corner numbers of a block face are legible on the
// atlas they anchor a position-based interpolation; other faces are numbered by lot order. Explicit overrides win.
const ANCHORS={'Lombard Street|N|500':[501,541],'Lombard Street|S|500':[500,542],'Lombard Street|N|600':[601,647],'Lombard Street|S|600':[600,640],'Lombard Street|N|700':[701,733],'Lombard Street|S|700':[700,746],'Seventh Street|E|500':[501,535],'Sixth Street|W|500':[502,530],'Sixth Street|E|500':[501,529],'St. Mary Street|N|600':[601,633],'St. Mary Street|N|700':[701,735]};
const faces=new Map();
for(const b of buildings){const e=b.front;if(!e||b.p.type==='wall')continue;const l=e.street?streetLocal(e.mx+e.nx*1.5,e.mz+e.nz*1.5):streetLocal((b.minX+b.maxX)/2,(b.minZ+b.maxZ)/2);let best=null;for(const r of streets){const along=r.axis==='u'?l.x:l.y,across=r.axis==='u'?l.y:l.x;if(along<r.from||along>r.to)continue;const d=Math.abs(across-r.at);if(d<(e.street?r.half+r.walk+1.5:60)&&(!best||d<best.d))best={r,d,along,across}}if(!best)continue;const {r,along,across}=best;
 let side,hund,lo,hi;if(r.axis==='u'){side=across<r.at?'N':'S';if(along>61){hund=500;lo=61;hi=Math.min(r.to,195)}else if(along>-73){hund=600;lo=-73;hi=61}else{hund=700;lo=Math.max(r.from,-207);hi=-73}}else{side=across>r.at?'E':'W';if(along>-6){hund=500;lo=-6;hi=108}else if(along>-109){hund=400;lo=-109;hi=-6}else{hund=300;lo=r.from;hi=-109}}
 const t=r.axis==='u'?(hi-along)/(hi-lo):(along-lo)/(hi-lo),key=r.name+'|'+side+'|'+hund;if(!faces.has(key))faces.set(key,[]);faces.get(key).push({b,t,r,side,hund})}
for(const [key,list] of faces){list.sort((x,y)=>x.t-y.t);const anchor=ANCHORS[key];list.forEach((it,i)=>{const odd=it.side==='N'||it.side==='E';let n;if(anchor){n=anchor[0]+2*Math.round(it.t*(anchor[1]-anchor[0])/2)}else n=it.hund+(odd?1:0)+2*i;const st=it.r.axis==='u'?it.r.name:'S. '+it.r.name;it.b.p.address=it.b.p.address||n+' '+st})}

