for(const b of named){const li=document.createElement('li'),bt=document.createElement('button');bt.innerHTML=`${b.p.name}<span>${LORE[b.p.name]?.[0]||(b.p.address?b.p.type+' · '+b.p.address:b.p.type)}</span>`;bt.onclick=()=>{goTo(b);$('#placelist').hidden=true};li.append(bt);$('#placeitems').append(li)}
function goTo(b){leaveOverhead();walkTarget=null;const e=b.front;if(!e){camera.position.set(b.maxX+6,EYE,b.maxZ+6);return}let d=e.clear<9?Math.max(2,e.clear-.5):Math.max(3,Math.min(18,e.clear*.7));if(e.street&&e.clear>=9)while(d<20&&!onStreet(e.mx+e.nx*d,e.mz+e.nz*d)&&!blocked(e.mx+e.nx*(d+1),e.mz+e.nz*(d+1)))d+=1;while(d>2&&blocked(e.mx+e.nx*d,e.mz+e.nz*d))d-=1;const x=e.mx+e.nx*d,z=e.mz+e.nz*d;camera.position.set(x,EYE,z);yaw=Math.atan2(-(e.mx-x),-(e.mz-z));pitch=Math.min(.6,Math.atan2(b.h*.55,d));camera.rotation.set(pitch,yaw,0)}

