renderer.domElement.addEventListener('pointerdown',e=>{walkTarget=null;vel.x=vel.z=0;if(e.button!==0&&e.pointerType==='mouse')return;drag=true;dragMoved=false;last=[e.clientX,e.clientY];renderer.domElement.setPointerCapture(e.pointerId);renderer.domElement.style.cursor='grabbing'});
